// Script URLs from the homepage (lab host only). If none, fall back to the homepage itself
// so its inline scripts still get scanned and the workflow never ends on empty output.
const HOME = 'http://testasp.vulnweb.com/';
const urls = new Set();
for (const item of $input.all()) {
  const html = String(item.json.html ?? '');
  for (const m of html.matchAll(/<script\b[^>]*?\bsrc\s*=\s*(["'])(.*?)\1/gi)) {
    try {
      const u = new URL(m[2].trim(), HOME);
      if (u.hostname === 'testasp.vulnweb.com' && u.protocol === 'http:' && !u.username && !u.password) urls.add(u.href);
    } catch (e) {}
  }
}
if (urls.size === 0) urls.add(HOME);
return [...urls].map(url => ({ json: { url } }));

const TEST_MODE = true;
const SALT_TEST_SAMPLE = true; // true = synthetic sample re-alerts on every manual run (de-dup would hide it after run 1)  // true = adds a clearly labelled SYNTHETIC sample (to prove the pipeline + de-dup). Set false for a real-only scan.
const patterns = [
  { name: 'api_key',           regex: /\bapi[_-]?key["']?\s*[:=]\s*["'`]([^"'`\r\n]{4,200})["'`]/gi },
  { name: 'token',             regex: /\b(?:access[_-]?token|auth[_-]?token|token)["']?\s*[:=]\s*["'`]([^"'`\r\n]{4,200})["'`]/gi },
  { name: 'secret',            regex: /\b(?:client[_-]?secret|app[_-]?secret|secret)["']?\s*[:=]\s*["'`]([^"'`\r\n]{4,200})["'`]/gi },
  { name: 'aws_access_key_id', regex: /\b((?:AKIA|ASIA)[0-9A-Z]{16})\b/g }
];
const urlItems = $('Extract JS URLs').all();
const sources = [];
$input.all().forEach((item, idx) => {
  const js = typeof item.json.js === 'string' ? item.json.js : '';
  if (!js) return;                                   // failed request
  const pi = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const p = (pi && typeof pi.item === 'number') ? pi.item : idx;
  sources.push({ sourceUrl: urlItems[p]?.json?.url ?? 'unknown', js });
});
if (TEST_MODE) sources.push({
  sourceUrl: 'http://testasp.vulnweb.com/[SYNTHETIC-TEST-SAMPLE].js',
  js: 'var api_key = "DEMO-NOT-REAL-KEY-12345";\nvar cfg = { "client_secret": "demoSecretValue9876" };\nvar aws = "AKIAIOSFODNN7EXAMPLE";\nvar token = "your_token_here";'
});

const mask = v => v.slice(0, 3) + '***';
const fp = s => { let a = 2166136261, b = 5381;
  for (let i = 0; i < s.length; i++) { a ^= s.charCodeAt(i); a = Math.imul(a, 16777619); b = (Math.imul(b, 33) + s.charCodeAt(i)) | 0; }
  return (a >>> 0).toString(16).padStart(8, '0') + (b >>> 0).toString(16).padStart(8, '0'); };

const out = [], seen = new Set();
for (const src of sources) for (const p of patterns) for (const m of src.js.matchAll(p.regex)) {
  const value = m[1];
  const fingerprint = fp(`${src.sourceUrl}|${p.name}|${value}`);
  if (seen.has(fingerprint)) continue;
  seen.add(fingerprint);
  let ctx = src.js.slice(Math.max(0, m.index - 80), m.index + m[0].length + 80);
  ctx = ctx.split(value).join(mask(value))
           .replace(/(["'`])([^"'`\r\n]{8,})\1/g, (a, q, s) => q + mask(s) + q)
           .replace(/\s+/g, ' ').slice(0, 250);
  out.push({ json: { sourceUrl: src.sourceUrl, pattern: p.name, maskedValue: mask(value), fingerprint, dedupeKey: (SALT_TEST_SAMPLE && src.sourceUrl.includes('SYNTHETIC-TEST')) ? fingerprint + '|' + Date.now() : fingerprint, context: ctx } });
}
return out;   // raw values never leave this node

// Parse the AI reply tolerantly. FALSE_POSITIVE is dropped. If the AI failed, send a REVIEW alert that shows WHY.
const OKV = ['LIKELY_SECRET', 'FALSE_POSITIVE', 'REVIEW'], OKS = ['HIGH', 'MEDIUM', 'LOW', 'INFO'];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const findings = $('Remove Duplicates').all();   // chain keeps 1:1 order with its input
const out = [];
$input.all().forEach((item, i) => {
  const finding = (findings[i] || {}).json || {};
  let raw = item.json.text ?? item.json.output ?? '';
  if (typeof raw !== 'string') raw = JSON.stringify(raw);
  let p = null;
  try {
    const m = raw.replace(/```json|```/gi, '').match(/\{[\s\S]*\}/);
    if (m) p = JSON.parse(m[0]);
  } catch (e) {}
  const verdict = String(p?.verdict ?? '').toUpperCase().trim();
  const severity = String(p?.severity ?? '').toUpperCase().trim();
  const summary = String(p?.summary ?? '').replace(/\s+/g, ' ').trim().slice(0, 100);
  const base = { pattern: finding.pattern, maskedValue: finding.maskedValue, fingerprint: finding.fingerprint, sourceUrl: esc(finding.sourceUrl) };
  if (OKV.includes(verdict) && OKS.includes(severity) && summary) {
    if (verdict === 'FALSE_POSITIVE') return;
    out.push({ json: { ...base, verdict, severity, summary: esc(summary) } });
  } else {
    const e = item.json.error;
    const why = e ? String(e.message ?? e) : 'unparseable AI reply: ' + raw.slice(0, 40);
    out.push({ json: { ...base, verdict: 'REVIEW', severity: finding.pattern === 'aws_access_key_id' ? 'MEDIUM' : 'LOW',
      summary: esc('AI unavailable - ' + why.replace(/\s+/g, ' ').slice(0, 70)), fallback: true } });
  }
});
return out;

